select * from customer limit 20
--what is the total revenue generated by mal and female
select gender ,sum(purchase_amount) as revenue from customer group by gender

--which customer used a discount but still spent more time than avg purchase purchase amount
select customer_id , purchase_amount from customer
where discount_applied = 'Yes' and purchase_amount > (select avg(purchase_amount) from customer)

--which are the top 5 product with the highest avg review rating
select item_purchased, avg(review_rating) as avg_review_rating from customer 
group by item_purchased 
order by avg_review_rating desc limit 5

--compare avg purchase amount between standared and express shipping
select shipping_type, round(avg(purchase_amount),2)
from customer
where shipping_type in ('Express','Standard')
group by shipping_type

--do subscribed customeres spend more ? compare avg spend and total revenue
--between subscribers and non subscriber 
select subscription_status ,
count(customer_id) as total_customers,
round(avg(purchase_amount),2) as avg_spend,
round(sum(purchase_amount),2) as total_revenue
from customer
group by subscription_status
order by avg_spend,total_revenue desc
from customer

--which 5 products have the highest percentage of purchases with discounts applied
select item_purchased,
ROUND(100 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE  0 END)/COUNT(*),2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5;

--segment customers into new , returning loyal based on their total number of previous purchases
--and show the count of each segement(CTE)
with customer_type as(
select customer_id,previous_purchases,
CASE 
    WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
	else 'Loyal'
	END as customer_segment
	from customer
)
select customer_segment , count(*) as "Number of Customers"
from customer_type
group by customer_segment

--what are top 3 most purchased product witing each category
with item_counts as (
select category ,
item_purchased,
COUNT(customer_id) as total_orders,
ROW_NUMBER() over (partition by category order by count(customer_id) DESC) as item_rank
from customer
group by category,item_purchased
)
select item_rank, category, item_purchased , total_orders
from item_counts
where item_rank <=3;

--are customers who are repeat buyers (more than 5 previos purchases) also likely to subscribe
select subscription_status,
count(customer_id) as repeat_buyers from customer
where previous_purchases >=5 
group by subscription_status

--what is the revenue contribtuin for each age grp
select age_group,
SUM(purchase_amount) as revenue
from customer
group by age_group
order by revenue desc;











